SourceCode.Declaration:
/// <summary>
/// Wave ID on sales and transfer order screens.
/// Stamps the latest wave ID onto order headers, order lines and shipment load lines so that
/// the screens can show, filter and sort on it without joining <c>METWaveLine</c> at runtime.
/// </summary>
/// <remarks>
/// All updates are set based and scoped to one wave and one document, so they use the
/// <c>METWaveLine</c> indexes (WaveId + DocumentNumber / DocNumRefRecId) and never touch other orders.
/// Data methods, database log and events are skipped so that update_recordset is not
/// downgraded to record-by-record updates by the overridden update() methods.
/// </remarks>
internal final class METWaveIdStampHelper
{
}

Method.Source:
/// <summary>
/// Stamps the wave ID on the sales order header, its lines that belong to the wave and its shipment load lines.
/// </summary>
/// <param name = "_waveId">Wave ID.</param>
/// <param name = "_salesId">Sales order number.</param>
public static void stampSalesOrder(METWaveId _waveId, SalesId _salesId)
{
    METSalesTable   metSalesTable;
    METSalesLine    metSalesLine;
    SalesTable      salesTable;
    METWaveLine     waveLine;

    if (!_waveId || !_salesId)
    {
        return;
    }

    ttsbegin;

    METWaveIdStampHelper::skipOverrides(metSalesLine);

    update_recordset metSalesLine
        setting WaveId = _waveId
        exists join waveLine
            where waveLine.WaveId           == _waveId
                && waveLine.DocumentNumber  == _salesId
                && waveLine.Type            == METType::SalesOrder
                && waveLine.DocNumRefRecId  == metSalesLine.SalesLine;

    METWaveIdStampHelper::skipOverrides(metSalesTable);

    update_recordset metSalesTable
        setting WaveId = _waveId
        exists join salesTable
            where salesTable.RecId      == metSalesTable.SalesTable
                && salesTable.SalesId   == _salesId;

    METWaveIdStampHelper::stampShipmentLoadLines(_waveId, _salesId);

    ttscommit;
}

/// <summary>
/// Stamps the wave ID on the transfer order header, its lines that belong to the wave and its shipment load lines.
/// </summary>
/// <param name = "_waveId">Wave ID.</param>
/// <param name = "_transferId">Transfer order number.</param>
public static void stampTransferOrder(METWaveId _waveId, InventTransferId _transferId)
{
    METInventTransferTableExt   metTransferTable;
    METInventTransferLine       metTransferLine;
    InventTransferTable         transferTable;
    METWaveLine                 waveLine;

    if (!_waveId || !_transferId)
    {
        return;
    }

    ttsbegin;

    METWaveIdStampHelper::skipOverrides(metTransferLine);

    update_recordset metTransferLine
        setting WaveId = _waveId
        exists join waveLine
            where waveLine.WaveId           == _waveId
                && waveLine.DocumentNumber  == _transferId
                && waveLine.Type            == METType::TransferOrder
                && waveLine.DocNumRefRecId  == metTransferLine.InventTransferLine;

    METWaveIdStampHelper::skipOverrides(metTransferTable);

    update_recordset metTransferTable
        setting WaveId = _waveId
        exists join transferTable
            where transferTable.RecId           == metTransferTable.InventTransferTable
                && transferTable.TransferId     == _transferId;

    METWaveIdStampHelper::stampShipmentLoadLines(_waveId, _transferId);

    ttscommit;
}

/// <summary>
/// Stamps the current wave of the sales order on its shipment load lines.
/// Used when load lines are created after the wave was assigned.
/// </summary>
/// <param name = "_salesId">Sales order number.</param>
public static void stampShipmentLoadLinesForSalesOrder(SalesId _salesId)
{
    METWaveIdStampHelper::stampShipmentLoadLines(METSalesTable::findBySalesId(_salesId).WaveId, _salesId);
}

/// <summary>
/// Stamps the current wave of the transfer order on its shipment load lines.
/// Used when load lines are created after the wave was assigned.
/// </summary>
/// <param name = "_transferId">Transfer order number.</param>
public static void stampShipmentLoadLinesForTransferOrder(InventTransferId _transferId)
{
    METWaveIdStampHelper::stampShipmentLoadLines(METInventTransferTableExt::findByTransferId(_transferId).WaveId, _transferId);
}

/// <summary>
/// Stamps the wave ID on the shipment load lines of an order that belong to the wave.
/// </summary>
/// <param name = "_waveId">Wave ID.</param>
/// <param name = "_orderNum">Sales order or transfer order number.</param>
private static void stampShipmentLoadLines(METWaveId _waveId, METDocumentNum _orderNum)
{
    METSalesOrderShipmentLoadLines  loadLines;
    METWaveLine                     waveLine;

    if (!_waveId || !_orderNum)
    {
        return;
    }

    ttsbegin;

    METWaveIdStampHelper::skipOverrides(loadLines);

    // OrderNum + LineNum is covered by SalesOrderIdx / ShipmentLineIdx and WaveId + DocumentNumber + LineNumber by WaveLineIdx.
    update_recordset loadLines
        setting WaveId = _waveId
        where loadLines.OrderNum == _orderNum
        exists join waveLine
            where waveLine.WaveId           == _waveId
                && waveLine.DocumentNumber  == loadLines.OrderNum
                && waveLine.LineNumber      == loadLines.LineNum;

    ttscommit;
}

/// <summary>
/// Keeps update_recordset set based by skipping overridden update(), database log and events.
/// </summary>
/// <param name = "_buffer">Table buffer to update.</param>
private static void skipOverrides(Common _buffer)
{
    _buffer.skipDataMethods(true);
    _buffer.skipDatabaseLog(true);
    _buffer.skipEvents(true);
}
